parents = [
    {
        "id": "parent_1",
        "text": "The company was founded in 2010. It grew steadily over the next decade, "
                "expanding into international markets and building a strong engineering team.",
    },
]

def build_children(parent):
    # building the parent child structure
    sentences = parent["text"].split(". ")
    return [
        {"id": f"{parent['id']}_child_{i}", "text": s.strip(), "parent_id": parent["id"]}
        for i, s in enumerate(sentences)
    ]

children = build_children(parents[0])
print("Child chunks used for search (embedding only the children):")
for child in children:
    print(f" {child['id']}: {child['text']!r}")

def search_and_retrieve_parent(query, children, parents_by_id):
    # retrieving the parent instead
    matched_child = next(c for c in children if query.lower() in c["text"].lower())
    parent = parents_by_id[matched_child["parent_id"]]
    return matched_child, parent

parents_by_id = {p["id"]: p for p in parents}
matched_child, parent = search_and_retrieve_parent("engineering team", children, parents_by_id)

print(f"\nQuery matched child: {matched_child['text']!r}")
print(f"Returning full parent instead: {parent['text']!r}")
